package com.nextenti.services.core.service.boq;import com.nextenti.services.common.exception.*;import com.nextenti.services.core.dto.boq.*;import com.nextenti.services.core.service.organization.OrganizationService;import com.nextenti.services.domain.entity.*;import com.nextenti.services.domain.repository.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.*;import java.util.*;
@Service public class BoqService {private final BoqRepository boqs;private final BoqItemRepository items;private final ProjectRepository projects;private final OrganizationService orgs;public BoqService(BoqRepository b,BoqItemRepository i,ProjectRepository p,OrganizationService o){boqs=b;items=i;projects=p;orgs=o;}private ProjectEntity project(UUID u,UUID id)throws SmartRoadException{ProjectEntity p=projects.findById(id).orElseThrow(()->nf("project.not.found"));orgs.requireMember(u,p.getOrganizationId());return p;}private SmartRoadException nf(String s){return new SmartRoadException(ApplicationLayer.SERVICE_LAYER,ErrorCodeMapping.DAO_NOT_FOUND,s);}
@Transactional public BoqResponse create(UUID u,UUID p,BoqRequest r)throws SmartRoadException{project(u,p);Boq b=new Boq();b.setId(UUID.randomUUID());b.setProjectId(p);b.setName(r.name());b.setDescription(r.description());b.setCreatedBy(u);b.setModifiedBy(u);return map(boqs.save(b));}@Transactional(readOnly=true)public List<BoqResponse> list(UUID u,UUID p)throws SmartRoadException{project(u,p);return boqs.findByProjectId(p).stream().map(this::map).toList();}@Transactional public BoqItemResponse addItem(UUID u,UUID bid,BoqItemRequest r)throws SmartRoadException{Boq b=boqs.findById(bid).orElseThrow(()->nf("boq.not.found"));project(u,b.getProjectId());BoqItem i=new BoqItem();i.setId(UUID.randomUUID());i.setBoqId(bid);i.setCreatedBy(u);i.setModifiedBy(u);apply(i,r);return itemMap(items.save(i));}@Transactional(readOnly=true)public List<BoqItemResponse> listItems(UUID u,UUID bid)throws SmartRoadException{Boq b=boqs.findById(bid).orElseThrow(()->nf("boq.not.found"));project(u,b.getProjectId());return items.findByBoqId(bid).stream().map(this::itemMap).toList();}private void apply(BoqItem i,BoqItemRequest r){i.setItemCode(r.itemCode());i.setDescription(r.description());i.setUnit(r.unit());i.setEstimatedQuantity(r.estimatedQuantity());i.setRate(r.rate());i.setActualQuantity(r.actualQuantity()==null?BigDecimal.ZERO:r.actualQuantity());i.setActualRate(r.actualRate()==null?r.rate():r.actualRate());}private BoqResponse map(Boq b){return new BoqResponse(b.getId(),b.getProjectId(),b.getName(),b.getDescription());}private BoqItemResponse itemMap(BoqItem i){BigDecimal est=i.getEstimatedQuantity().multiply(i.getRate());BigDecimal act=i.getActualQuantity().multiply(i.getActualRate());return new BoqItemResponse(i.getId(),i.getBoqId(),i.getItemCode(),i.getDescription(),i.getUnit(),i.getEstimatedQuantity(),i.getRate(),est,i.getActualQuantity(),i.getActualRate(),act,i.getActualQuantity().subtract(i.getEstimatedQuantity()),act.subtract(est));}}
